using System;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Base;
namespace WildsEngine.Discoveries.Narratives { public sealed class DiscoveryNarrativeRelationshipDefinition:IdentifierBase,IDiscoveryNarrativeRelationshipDefinition { public DiscoveryNarrativeRelationshipDefinition(Guid id,string slug,string left,string right,string relationship):base(id,slug){if(string.IsNullOrWhiteSpace(left)||string.IsNullOrWhiteSpace(right)||string.IsNullOrWhiteSpace(relationship))throw new ArgumentException("Relationship vocabulary is required.");LeftSemanticKey=left.Trim();RightSemanticKey=right.Trim();RelationshipKey=relationship.Trim();} public string LeftSemanticKey{get;}public string RightSemanticKey{get;}public string RelationshipKey{get;} } }
